  end


  always @(*) begin
    k28_6 = (s6 == 6'b001111) | (s6 == 6'b110000);
  end

  reg v4;
  reg [2:0] y;

  always @(*) begin
    v4 = 1'b1;
    y = 3'd0;
    case(s4)
      4'b1011, 4'b0100: y = 3'd0;
      4'b1001: y = 3'd1;
      4'b0101: y = 3'd2;
      4'b1100, 4'b0011: y = 3'd3;
      4'b1101, 4'b0010: y = 3'd4;
      4'b1010: y = 3'd5;
      4'b0110: y = 3'd6;
      4'b1110, 4'b0001, 4'b0111, 4'b1000: y = 3'd7;
      default: v4 = 1'b0;
    endcase
  end

  wire rdmid;assign rdmid = (pos6)? 1'b1 : 
                 (neg6)? 1'b0 : dispin;
  wire disp6_err;assign disp6_err = pos6 & dispin | neg6 & ~dispin;
  wire disp4_err;assign disp4_err = pos4 & ~rdmid | neg4 & rdmid;
  wire conf;assign conf = pos6 & pos4 | neg6 & neg4;
  wire xa;assign xa = (x == 5'd17) | (x == 5'd18) | (x == 5'd20);
  wire xb;assign xb = (x == 5'd11) | (x == 5'd13) | (x == 5'd14);
  wire xk;assign xk = (x == 5'd23) | (x == 5'd27) | (x == 5'd29) | (x == 5'd30);
  wire isP7;assign isP7 = (s4 == 4'b1110) | (s4 == 4'b0001);
  wire isA7;assign isA7 = (s4 == 4'b0111) | (s4 == 4'b1000);
  wire bad_p7;assign bad_p7 = isP7 & (xa & (s4 == 4'b1110) | xb & (s4 == 4'b0001) | k28_6);
  wire ok_a7;assign ok_a7 = xa & (s4 == 4'b0111) | xb & (s4 == 4'b1000) | xk | k28_6 & (x == 5'd28);
  wire bad_a7;assign bad_a7 = isA7 & ~ok_a7;
  wire kx7;assign kx7 = isA7 & xk;
  wire kflag;assign kflag = k28_6 | kx7;
  assign dataout = { kflag, y, x };
  assign dispout = (pos4)? 1'b1 : 
                   (neg4)? 1'b0 : rdmid;
  assign code_err = ~v6 | ~v4 | conf | bad_p7 | bad_a7;
  assign disp_err = disp6_err | disp4_err;

endmodule
